// run with: bare (needs bare 1.32+)
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const Corestore = require('corestore')
const id = require('hypercore-id-encoding')
const { create_autobee } = require('autobee')
const { create_autodrive } = require('autodrive')
const drive_link = require('drive-link')
const drive_loader = require('drive-loader')
const packs = require('./')

const { decode } = drive_link()
let failed = 0
main().then(done)

async function main () {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'packs-test-'))
  const store_dir = path.join(root, 'store')
  const store = new Corestore(store_dir)
  const vault = await make_vault(store)
  const pkgs = packs(vault)
  // a small app folder to turn into a pack
  const app = path.join(root, 'app')
  fs.mkdirSync(path.join(app, 'lib'), { recursive: true })
  fs.writeFileSync(path.join(app, 'main.js'), "module.exports = require('./lib/hi.js')")
  fs.writeFileSync(path.join(app, 'lib', 'hi.js'), "module.exports = 'hi from a pack'")
  const before = count_cores(store_dir)
  const link = await pkgs.create('hello', app)
  const { key } = decode(link)
  check('create gives a dat:// link with only the key, no version', link === `dat://${key[2]}` && !key[0] && !key[3])
  check('list and get show the pack', (await pkgs.list()).join() === 'hello' && await pkgs.get('hello') === link)
  check('the same name is refused', await fails(pkgs.create('hello', app)))
  const pin = decode(await pkgs.pin('hello')).key
  check('pin gives a pinned link of the same drive with a length and a hash', pin[2] === key[2] && Number(pin[0]) > 0 && pin[3].length === 64)
  const record = await vault.vault_get('packs/hello')
  const drive = create_autodrive({ store: store.namespace(record.namespace), bootstrap: id.decode(key[2]) })
  await drive.ready()
  const pinned = drive.base.view.drive.checkout(Number(pin[0]))
  check('the pack runs straight from its drive at the pinned length', await drive_loader({ drive: pinned, file: '/main.js' }) === 'hi from a pack')
  await pinned.close()
  await drive.close()
  await pkgs.create('other', app)
  const with_both = count_cores(store_dir)
  await pkgs.remove('hello')
  check('remove deletes the name', !(await pkgs.get('hello')) && (await pkgs.list()).join() === 'other')
  check('remove deletes the pack cores from disk and keeps the other pack', count_cores(store_dir) === with_both - (with_both - before) / 2, `${before} before, ${with_both} with both packs, ${count_cores(store_dir)} after remove`)
  check('removing an unknown pack is refused', await fails(pkgs.remove('hello')))
  check('pinning an unknown pack is refused', await fails(pkgs.pin('hello')))
  await store.close()
  fs.rmSync(root, { recursive: true, force: true })
}

/***************************************
HELPERS
***************************************/
function check (name, ok, note = '') {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}${note ? `  (${note})` : ''}`)
  if (!ok) failed++
}

function done () {
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) throw new Error('packs tests failed')
}

function fails (promise) { return promise.then(() => false, () => true) }

// a small stand in for the vault: the same calls packs uses, on a real autobee
async function make_vault (store) {
  const bee = create_autobee({ store: store.namespace('vault-bee') })
  await bee.ready()
  return { store, get_vault_bee: () => bee, vault_put: (key, value) => bee.put(key, value), vault_get: async key => (await bee.get(key))?.value || null, vault_del: key => bee.del(key) }
}

// how many cores are stored on disk
function count_cores (folder) {
  const cores = path.join(folder, 'cores')
  if (!fs.existsSync(cores)) return 0
  return fs.readdirSync(cores).flatMap(a => fs.readdirSync(path.join(cores, a)).flatMap(b => fs.readdirSync(path.join(cores, a, b)))).length
}
